M(gs, r"""
public static synchronized String fenceWho(@PKG@.Guild g, String us, String k) {
  String first = null;
  int n = 0;
  java.util.Iterator it = g.pnet.entrySet().iterator();
  while (it.hasNext()) {
    java.util.Map.Entry e = (java.util.Map.Entry) it.next();
    String q = (String) e.getKey();
    if (q.equals(k) || !(q.equals(us) || q.startsWith(us + "-"))) continue;
    long[] v = (long[]) e.getValue();
    if (v[0] - v[1] <= 0L || !sameBlocked(k, q)) continue;
    n++;
    if (first == null || q.compareTo(first) < 0) first = q;
  }
  if (first == null) return "another profile";
  return profName(first) + (n > 1 ? " and others" : "");
}""")
